import React, { useState } from 'react';
import { Image, Box, Input, Stack, Flex, Center, Text, InputGroup, InputLeftElement, InputRightElement, Button, VStack } from '@chakra-ui/react';
import { EmailIcon, UnlockIcon, CheckIcon } from '@chakra-ui/icons';
import {useNavigate } from 'react-router-dom';
import axios from "axios";

const Login = () => {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const navigate = useNavigate()


  const handleSubmit = (e) => {
    e.preventDefault(); // Prevents the default form submission behavior
    axios.post('http://localhost:3001/login', { email, password })
      .then(result => {
        console.log(result)
        if(result.data === "Success"){
          navigate("/")
        }
      })
      .catch(err => console.log(err));
  };

  return (
    
    <VStack
      width="100vw"
      height="100vh"
      alignItems="center"
      justifyContent="center"
      position="relative" // Allow pseudo-element positioning
      _before={{
        content: '""',
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        backgroundImage: 'url("/Fields.jpeg")', // Adjust to the correct path of your image
        backgroundSize: 'cover',
        backgroundPosition: 'center',
        zIndex: -1,
        opacity: 0.5, // Image opacity
      }}
      _after={{
        content: '""',
        position: 'absolute',
        top: 0,
        left: 0,
        width: '100%',
        height: '100%',
        backgroundColor: 'rgba(173, 216, 230, 0.5)', // Light blue tint with transparency
        zIndex: -1,
      }}>



      <Box width="100%" height="20vh" bg="white" color="white" padding="10px" display="flex" justifyContent="center" alignItems="center">
        <Image src="AdamsWings.png" alt="Adams Wings" height='100%'/>

      </Box>
      

      <Flex flex="1" alignItems="center" justifyContent="center">
        <Center>
          <Stack spacing={10} align="center">
            {/*<Text fontSize="4xl" fontWeight="bold" color="black" fontFamily="sans-serif">Adam's Foods Inventory System</Text>*/}
            <VStack bg='white' borderRadius="md" width='60vh' height='50vh' >
            <Text fontSize="4xl" fontWeight="bold" color="black" fontFamily="sans-serif" marginTop='10px'>Login</Text>
            <form onSubmit={handleSubmit}> 
              <Stack spacing={3}>
                <InputGroup>
                  <InputLeftElement pointerEvents='none'>
                    <EmailIcon color='gray.300' />
                  </InputLeftElement>
                  <Input type='email' placeholder='Enter Email' onChange={(e) => setEmail(e.target.value)} />
                </InputGroup>

                <InputGroup>
                  <InputLeftElement pointerEvents='none' color='gray.300' fontSize='1.2em'>
                    <UnlockIcon />
                  </InputLeftElement>
                  <Input type='password' placeholder='Enter Password' onChange={(e) => setPassword(e.target.value)} />
                  <InputRightElement>
                    <CheckIcon color='green.500' />
                  </InputRightElement>
                </InputGroup>

                <Flex width="100%" justifyContent="center" mt={5}>
                  <Button bg="lightblue" size="lg" width="45%" marginTop='10px' type="submit">Login</Button>
                </Flex>
              </Stack>
            </form>
          </VStack>
          </Stack>
        </Center>
      </Flex>
    </VStack>
  );
}

export default Login;
